#include <stdio.h>
int adj[4][4]={0}, vis[4]={0}, stk[4]={0};
int dfs(int u, int p, int n){
    vis[u]=1; stk[u]=1;
    for(int v=0;v<n;v++) if(adj[u][v]){
        if(!vis[v]){ if(dfs(v,u,n)) return 1; }
        else if(v!=p && stk[v]) return 1;
    }
    stk[u]=0; return 0;
}
int main(void){
    int n=4;
    int e[][2]={{0,1},{1,2},{2,0},{2,3}};  /* 三角形 0-1-2 构成环 */
    int m=4;
    for(int k=0;k<m;k++){ adj[e[k][0]][e[k][1]]=1; adj[e[k][1]][e[k][0]]=1; }
    int cyc=0;
    for(int i=0;i<n;i++) if(!vis[i]) if(dfs(i,-1,n)){ cyc=1; break; }
    printf("has cycle: %s\n", cyc ? "yes" : "no");
    return 0;
}
